use std::path::Path;
use sysmlv2_model::{model::{Model, GraphFormat}, json::{Derived, ResolvedModel}};
fn library(model: &mut Model, path: &Path) {
    let mut entries: Vec<_> = std::fs::read_dir(path).unwrap().map(|e| e.unwrap().path()).collect();
    entries.sort();
    for entry in entries {
        if entry.is_dir() { library(model, &entry); }
        else if matches!(entry.extension().and_then(|x|x.to_str()), Some("sysml"|"kerml")) {
            assert!(model.add_library_source(entry.to_string_lossy(), &std::fs::read_to_string(&entry).unwrap()).diagnostics.is_empty());
        }
    }
}
const SOURCE: &str = "package Probe {
 behavior B {step enclosed; composite step owned;}
 step outer {step enclosed; composite step owned;}
 struct S {step plain; composite step owned;}
 feature structural:S {composite step owned;}
 step unowned;
}";
fn main() { std::thread::Builder::new().stack_size(16*1024*1024).spawn(|| {
 let mut model=Model::with_graph_format(GraphFormat::CanonicalV3);
 library(&mut model,Path::new("vendor/sysml-library/sources"));
 assert!(model.add_source("step-contexts.kerml", SOURCE).diagnostics.is_empty());
 let mut r=ResolvedModel::build(&model);
 let root=r.resolve_qualified("Probe").unwrap(); r.implied_relationships(root);
 let roles = ["Performances::performances", "Performances::Performance::enclosedPerformances", "Performances::Performance::subperformances", "Objects::Object::ownedPerformances"];
 let targets: Vec<_> = roles.iter().map(|n|r.resolve_qualified(n).unwrap()).collect();
 for singular in ["Performances::Performance::enclosedPerformance", "Performances::Performance::subperformance", "Objects::Object::ownedPerformance"] {
  assert!(r.resolve_qualified(singular).is_none());
 }
 for (name, owner) in [("B::enclosed",Some("B")),("B::owned",Some("B")),("outer::enclosed",Some("outer")),("outer::owned",Some("outer")),("S::plain",Some("S")),("S::owned",Some("S")),("structural::owned",Some("structural")),("unowned",None)] {
  let e=r.resolve_qualified(&format!("Probe::{name}")).unwrap();
  let expected_owner=owner.map(|n|r.resolve_qualified(&format!("Probe::{n}")).unwrap());
  let owning_type=match r.derived(e,"owningType") {Derived::Value(v)=>v.element(),_=>None};
  assert_eq!(owning_type,expected_owner,"{name}");
  let paths:Vec<_>=targets.iter().map(|t|r.conforms_with_implied(e,*t)).collect();
  assert!(paths[0],"missing generic performance path: {name}");
  println!("{name}: ownerKind={:?}, composite={:?}, paths={paths:?}",owning_type.map(|o|r.element_type(o)),r.is_composite(e));
 }
 }).unwrap().join().unwrap();}
